import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { describe, expect, it } from 'vitest'
import { extractText, MAX_PDF_PAGES, pdfToText, UnsupportedDocumentError } from './extract.ts'
import { chunkText } from './chunk.ts'

// Fixtures are generated by scripts/make-pdf-fixtures.py (reportlab / pypdf / LibreOffice); expected text was cross-checked with pdftotext.
const fx = (name: string) => new Uint8Array(readFileSync(resolve(process.cwd(), 'supabase/functions/_shared/core/docs/fixtures', name)))
const reason = async (name: string) => (await pdfToText(fx(name)).catch((e) => e)) as Error

describe('PDF text extraction', () => {
  it('reads a simple one-page PDF', async () => {
    const t = await extractText(fx('text-simple.pdf'), 'application/pdf', 'invoice.pdf')
    expect(t).toContain('Invoice 1042')
    expect(t).toContain('Customer: Northwind Traders')
    expect(t).toContain('Total due: $1,250.00 by 2026-11-30.')
  })

  it('keeps every page, in order, with accented characters and em dashes intact', async () => {
    const t = await pdfToText(fx('text-multipage.pdf'))
    const a = t.indexOf('Page one clause'), b = t.indexOf('Page two clause'), c = t.indexOf('Page three clause')
    expect(a).toBeGreaterThanOrEqual(0)
    expect(a).toBeLessThan(b)
    expect(b).toBeLessThan(c)
    expect(t).toContain('Café résumé naïve — signed in Zürich.')
    expect(t).toMatch(/Widget\s+4\s+\$45\.00/)
    expect(t).not.toContain('[Note:')
  })

  it('reads a PDF produced by a real word processor (embedded subset fonts)', async () => {
    const t = await pdfToText(fx('from-libreoffice.pdf'))
    expect(t).toContain('Service Agreement')
    expect(t).toContain('Café résumé naïve — “quotes”.')
    expect(t).toContain('• Deliver by Dec 15')
    expect(t).toContain('Widget')
    expect(t).toContain('$45.00')
  })

  it('is detected by content, not just by file name or MIME type', async () => {
    expect(await extractText(fx('text-simple.pdf'), null, 'upload.pdf')).toContain('Invoice 1042')
    expect(await extractText(fx('text-simple.pdf'), 'application/pdf', 'no-extension')).toContain('Invoice 1042')
  })

  it('output feeds the chunker/search pipeline', async () => {
    const chunks = chunkText(await pdfToText(fx('text-multipage.pdf')))
    expect(chunks.length).toBeGreaterThan(0)
    expect(chunks.join(' ')).toContain('net 30')
  })
})

describe('PDFs we cannot read are reported honestly, never faked', () => {
  it('scanned (image-only) PDFs say they are scans and that OCR is not supported', async () => {
    const e = await reason('scanned.pdf')
    expect(e).toBeInstanceOf(UnsupportedDocumentError)
    expect(e.message).toMatch(/scanned images/i)
    expect(e.message).toMatch(/OCR/)
  })

  it('a mixed PDF returns the real text and states which pages were left out', async () => {
    const t = await pdfToText(fx('mixed.pdf'))
    expect(t).toContain('This first page has real text that must be extracted.')
    expect(t).toContain('The last page also has real text to extract.')
    expect(t).toContain('[Note: 1 of 3 pages had no readable text (scanned images) and is not included.]')
  })

  it('password-protected PDFs ask for an unprotected copy', async () => {
    const e = await reason('encrypted.pdf')
    expect(e).toBeInstanceOf(UnsupportedDocumentError)
    expect(e.message).toMatch(/password/i)
  })

  it('truncated / damaged PDFs fail with a clear reason, not a stack trace', async () => {
    const e = await reason('corrupt.pdf')
    expect(e).toBeInstanceOf(UnsupportedDocumentError)
    expect(e.message).toMatch(/damaged|cannot be read/i)
  })

  it('non-PDF content with a .pdf name, and empty files, are rejected up front', async () => {
    const text = new TextEncoder().encode('Hello, I am definitely not a PDF.')
    await expect(extractText(text, 'application/pdf', 'fake.pdf')).rejects.toThrow(/not a valid PDF/)
    await expect(extractText(new Uint8Array(), 'application/pdf', 'empty.pdf')).rejects.toThrow(/not a valid PDF/)
  })

  it(`refuses documents over ${MAX_PDF_PAGES} pages with the page count`, async () => {
    const e = await reason('too-many-pages.pdf')
    expect(e).toBeInstanceOf(UnsupportedDocumentError)
    expect(e.message).toContain('301 pages')
    expect(e.message).toContain(`limit is ${MAX_PDF_PAGES}`)
  })

  it('every failure is a user-facing UnsupportedDocumentError (so the document row shows the reason)', async () => {
    for (const f of ['scanned.pdf', 'encrypted.pdf', 'corrupt.pdf', 'too-many-pages.pdf']) {
      expect(await reason(f)).toBeInstanceOf(UnsupportedDocumentError)
    }
  })
})

describe('PDF safety', () => {
  it('a PDF carrying JavaScript is read as plain text and the script never runs', async () => {
    const g = globalThis as Record<string, unknown>
    const alerts: unknown[] = []
    g.app = { alert: (m: unknown) => alerts.push(m) }
    try {
      const t = await pdfToText(fx('with-javascript.pdf'))
      expect(t).toContain('Invoice 1042')
      expect(alerts).toEqual([])
    } finally { delete g.app }
  })

  it('the bundled pdf.js contains no dynamic code evaluation (eval / new Function)', () => {
    const src = readFileSync(resolve(process.cwd(), 'node_modules/unpdf/dist/pdfjs.mjs'), 'utf8')
    expect(src).not.toMatch(/new Function\s*\(/)
    expect(src).not.toMatch(/[^\w.$]eval\s*\(/)
  })

  it('does not detach or mutate the caller\'s buffer', async () => {
    const bytes = fx('text-simple.pdf')
    const before = bytes.length
    await pdfToText(bytes)
    expect(bytes.length).toBe(before)
    await pdfToText(bytes) // reusable
  })
})

import { handleDocumentProcess, type DocumentProcessDeps } from '../handlers/documentProcess.ts'

describe('uploading a PDF end to end (document-process handler)', () => {
  const ORG = '22222222-2222-4222-8222-222222222222'
  const ID = '11111111-1111-4111-8111-111111111111'
  function run(file: string, name = file) {
    const state = { chunks: [] as string[], result: null as null | Record<string, unknown> }
    const d: DocumentProcessDeps = {
      userId: 'u1', getRole: async () => 'member',
      loadDocument: async (id) => ({ id, org_id: ORG, name, mime_type: 'application/pdf', storage_path: `${ORG}/${name}` }),
      download: async () => fx(file),
      markProcessing: async () => true,
      saveChunks: async (_o, _d, c) => { state.chunks = c },
      saveResult: async (_i, r) => { state.result = r as Record<string, unknown> },
    }
    return { d, state }
  }

  it('a text PDF becomes ready and searchable', async () => {
    const { d, state } = run('text-multipage.pdf')
    expect((await handleDocumentProcess(d, { document_id: ID })).body).toMatchObject({ status: 'ready', searchable: true })
    expect(state.chunks.join(' ')).toContain('invoices are payable net 30')
    expect(state.result).toMatchObject({ status: 'ready' })
  })

  it.each([
    ['scanned.pdf', /scanned images/],
    ['encrypted.pdf', /password/],
    ['corrupt.pdf', /damaged/],
    ['too-many-pages.pdf', /301 pages/],
  ])('%s fails visibly with its reason, and nothing is indexed', async (file, why) => {
    const { d, state } = run(file)
    const r = await handleDocumentProcess(d, { document_id: ID })
    expect(r.body).toMatchObject({ status: 'failed' })
    expect(String(r.body.error)).toMatch(why)
    expect(state.result).toMatchObject({ status: 'failed' })
    expect(String(state.result?.error)).toMatch(why)
    expect(state.chunks).toEqual([])
  })
})
